from google.cloud import vision

def get_image_annotator_client():
    return vision.ImageAnnotatorClient()

import dataclasses
from typing import List, Dict, Any

@dataclasses.dataclass
class VisionRequest:
    image_bytes: bytes
    mime_type: str = "image/jpeg" # Default to JPEG, can be overridden

@dataclasses.dataclass
class Label:
    name: str
    confidence: float

@dataclasses.dataclass
class DetectedText:
    text: str
    bounds: List[Dict[str, Any]]

@dataclasses.dataclass
class ImageProperties:
    colors: List[Dict[str, Any]]

@dataclasses.dataclass
class SafeSearchAnnotation:
    adult: str
    spoof: str
    medical: str
    violence: str
    racy: str

@dataclasses.dataclass
class WebDetection:
    full_matching_images: List[Dict[str, Any]]
    partial_matching_images: List[Dict[str, Any]]
    web_entities: List[Dict[str, Any]]

@dataclasses.dataclass
class ImageContext:
    lat_long_rect: Dict[str, Any] = None
    language_hints: List[str] = None

@dataclasses.dataclass
class ImageResponse:
    labels: List[Label] = dataclasses.field(default_factory=list)
    text_annotations: List[DetectedText] = dataclasses.field(default_factory=list)
    full_text_annotation: Dict[str, Any] = dataclasses.field(default_factory=dict)
    safe_search_annotation: SafeSearchAnnotation = None
    localized_object_annotations: List[Dict[str, Any]] = dataclasses.field(default_factory=list)
    web_detection: WebDetection = None
    image_properties: ImageProperties = None
    error: Dict[str, Any] = dataclasses.field(default_factory=dict)
    description: str = None # For image description results

from google.cloud import vision
from vision_client import get_image_annotator_client
from vision_models import VisionRequest, ImageResponse

def describe_image(payload, config=None):
    config = config or {}
    client = get_image_annotator_client()
    image = vision.Image(content=payload["image_bytes"])

    # Use label detection to generate a description
    response = client.label_detection(image=image, max_results=int(config.get("max_labels", 5)))

    if response.error.message:
        raise RuntimeError(response.error.message)

    labels = [label.description for label in response.label_annotations]

    description = "A picture of "
    if labels:
        if len(labels) == 1:
            description += labels[0]
        elif len(labels) == 2:
            description += f"{labels[0]} and {labels[1]}"
        else:
            description += ", ".join(labels[:-1]) + f", and {labels[-1]}"
    else:
        description = "An image with no clear description."

    return {"description": description}

from google.cloud import vision
from vision_client import get_image_annotator_client
from vision_models import VisionRequest, ImageResponse, DetectedText

def detect_image_text(payload, config=None):
    config = config or {}
    client = get_image_annotator_client()
    image = vision.Image(content=payload["image_bytes"])

    response = client.text_detection(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    # The first text annotation is usually the full text detected in the image.
    # Subsequent annotations are individual words or lines.
    texts = []
    if response.text_annotations:
        for text_annotation in response.text_annotations:
            texts.append(DetectedText(
                text=text_annotation.description,
                bounds=[
                    {"x": v.x, "y": v.y} 
                    for v in text_annotation.bounding_poly.vertices
                ]
            ))

    # Return the full text description as well
    full_text = response.full_text_annotation.text if response.full_text_annotation else ""

    return {"full_text": full_text, "detected_texts": [t.__dict__ for t in texts]}

from google.cloud import vision
from vision_client import get_image_annotator_client
from vision_models import VisionRequest, ImageResponse, SafeSearchAnnotation

def score_image_safety(payload, config=None):
    config = config or {}
    client = get_image_annotator_client()
    image = vision.Image(content=payload["image_bytes"])

    response = client.safe_search_detection(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    safe_search = response.safe_search_annotation
    if safe_search:
        safety_scores = SafeSearchAnnotation(
            adult=safe_search.adult.name,
            spoof=safe_search.spoof.name,
            medical=safe_search.medical.name,
            violence=safe_search.violence.name,
            racy=safe_search.racy.name,
        )
    else:
        safety_scores = SafeSearchAnnotation(
            adult="UNKNOWN", spoof="UNKNOWN", medical="UNKNOWN", 
            violence="UNKNOWN", racy="UNKNOWN"
        )

    return {"safety_scores": safety_scores.__dict__}

import google.generativeai as genai
import os

def image_summary(payload, config=None):
    config = config or {}
    genai.configure(api_key=os.environ.get("GEMINI_API_KEY"))

    model = genai.GenerativeModel('gemini-pro')

    analysis_results = payload.get("analysis_results", {})

    prompt = "Summarize the following image analysis results in a concise manner:\n\n"
    for key, value in analysis_results.items():
        prompt += f"{key}: {value}\n"

    response = model.generate_content(prompt)

    return {"summary": response.text}

from google.cloud import translate_v3 as translate
import os

def alt_text_translate(payload, config=None):
    config = config or {}
    client = translate.TranslationServiceClient()

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT") # Or pass as config
    location = config.get("location", "global")

    parent = f"projects/{project_id}/locations/{location}"

    text_to_translate = payload["text"]
    target_language_code = payload.get("target_language", "es") # Default to Spanish

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text_to_translate],
            "mime_type": "text/plain",
            "source_language_code": "en", # Assuming source is English
            "target_language_code": target_language_code,
        }
    )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)

    return {"translated_text": translations[0] if translations else ""}
